     <!-- R25: the filter toolbar — logical groups (period / scope /\n             dates / dimensions) each in their own pocket, uniform\n             34px controls, inline من/إلى labels, and the new month\n             quick-filters: الشهر الحالي (whole latest month) and\n             الشهر السابق (the month before it) replace آخر شهر. -->\n        <div class=\"filters\">\n          <div class=\"fgroup\" data-fg=\"period\">\n            <div class=\"qp\" id=\"qp\">\n              <button class=\"qp-btn\" data-qp=\"last1\" data-i18n=\"f_last1\" type=\"button\">آخر يوم</button>\n              <button class=\"qp-btn\" data-qp=\"last7\" data-i18n=\"f_last7\" type=\"button\">آخر أسبوع</button>\n              <button class=\"qp-btn\" data-qp=\"curMonth\" data-i18n=\"f_cur\" type=\"button\">الشهر الحالي</button>\n              <button class=\"qp-btn\" data-qp=\"prevMonth\" data-i18n=\"f_prev\" type=\"button\">الشهر السابق</button>\n              <button class=\"qp-btn on\" data-qp=\"all\" data-i18n=\"f_all\" type=\"button\">الكل</button>\n            </div>\n          </div>\n          <div class=\"scope-seg\" id=\"scopeSeg\" role=\"group\" data-i18n-title=\"sc_tt\" title=\"scope\">\n            <button class=\"scope-btn\" data-scope=\"base\" data-i18n=\"sc_base\" type=\"button\">أساسي</button>\n            <button class=\"scope-btn\" data-scope=\"ot\" data-i18n=\"sc_ot\" type=\"button\">إضافي</button>\n            <button class=\"scope-btn on\" data-scope=\"both\" data-i18n=\"sc_both\" type=\"button\">الاثنين</button>\n          </div>\n          <div class=\"fgroup\" data-fg=\"dates\">\n            <select id=\"fMonth\" data-i18n-title=\"f_month\" title=\"الشهر\"></select>\n            <div class=\"range-pick\">\n              <span class=\"dp-lab\" data-i18n=\"f_from\">من</span>\n              <input type=\"date\" id=\"fFrom\" title=\"من\" data-i18n-title=\"f_from\">\n              <span class=\"sep\">—</span>\n              <span class=\"dp-lab\" data-i18n=\"f_to\">إلى</span>\n              <input type=\"date\" id=\"fTo\" title=\"إلى\" data-i18n-title=\"f_to\">\n            </div>\n          </div>\n          <div class=\"fgroup\" data-fg=\"mhmy\">\n            <select id=\"mhMonth\" data-i18n-title=\"f_month\" title=\"الشهر\"></select>\n            <select id=\"mhYear\" data-i18n-title=\"f_year\" title=\"السنة\"></select>\n          </div>\n          <div class=\"fgroup\" data-fg=\"dims\">\n            <select id=\"fLine\" title=\"الخط\" data-i18n-title=\"f_line\"></select>\n            <select id=\"fSection\" title=\"القسم\" data-i18n-title=\"f_section\"></select>\n            <select id=\"fSup\" title=\"المشرف\" data-i18n-title=\"f_sup\"></select>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"pages\">\n\n        <!-- ========== Overview ========== -->\n        <section class=\"page on\" id=\"page-overview\">\n          <div class=\"kpi-grid\" id=\"ovKpis\"></div>\n          <div class=\"card hero-wrap sp-16\">\n            <div class=\"card-head\">\n              <div>\n                <h4 data-i18n=\"c_ovTrend:0\">الإنتاج اليومي مقابل الهدف</h4>\n                <span class=\"en\" data-i18n=\"c_ovTrend:1\">DAILY&nbsp;OUTPUT&nbsp;VS&nbsp;TARGET</span>\n              </div>\n              <span class=\"hero-head-chip\" id=\"ovHeroChip\"></span>\n            </div>\n            <div class=\"chart\" id=\"ovTrend\"></div>\n          </div>\n          <div class=\"grid-3\">\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_ovTop:0\">أفضل الخطوط تحقيقًا</h4><span class=\"en\" data-i18n=\"c_ovTop:1\">TOP&nbsp;LINES</span></div>\n              </div>\n              <div class=\"chart\" id=\"ovTop\"></div>\n            </div>\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_ovDonut:0\">توزيع الإنتاج على الأقسام</h4><span class=\"en\" data-i18n=\"c_ovDonut:1\">OUTPUT&nbsp;BY&nbsp;SECTION</span></div>\n              </div>\n              <div class=\"chart\" id=\"ovDonut\"></div>\n            </div>\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_ovDual:0\">الكفاءة والحضور اليومي</h4><span class=\"en\" data-i18n=\"c_ovDual:1\">EFFICIENCY&nbsp;&amp;&nbsp;ATTENDANCE</span></div>\n              </div>\n              <div class=\"chart\" id=\"ovDual\"></div>\n            </div>\n          </div>\n        </section>\n\n        <!-- ========== Manager home (R30 — Grafik view: GÜN/HAFTA/AY) ==========\n             Mirrors the manager's Turkish Excel \"Grafik\" sheet: a 3-box\n             granularity switch (day/week/month) driving 6 metric charts\n             (efficiency + target line · output per man-shift · total\n             workers · avg model time · overtime % · absenteeism %).\n             Shown ONLY to users the dev picks in settings (رئيسية المدير)\n             — everyone else keeps the classic overview above. -->\n        <section class=\"page\" id=\"page-mhome\">\n          <div class=\"mh-seg\" id=\"mhSeg\">\n            <button class=\"mh-box on\" data-mh=\"day\" type=\"button\"><b data-i18n=\"mh_day\">يومي</b><span class=\"en\">GÜN</span></button>\n            <button class=\"mh-box\" data-mh=\"week\" type=\"button\"><b data-i18n=\"mh_week\">أسبوعي</b><span class=\"en\">HAFTA</span></button>\n            <button class=\"mh-box\" data-mh=\"month\" type=\"button\"><b data-i18n=\"mh_month\">شهري</b><span class=\"en\">AY</span></button>\n          </div>\n          <div class=\"grid-3\">\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_mhEff:0\">كفاءة التشغيل</h4><span class=\"en\" data-i18n=\"c_mhEff:1\">VERİMLİLİK · EFFICIENCY</span></div>\n              </div>\n              <div class=\"chart\" id=\"mhEff\"></div>\n            </div>\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_mhProd:0\">الإنتاج لكل عامل-وردية</h4><span class=\"en\" data-i18n=\"c_mhProd:1\">ÜRETİM / ADAM·VARDİYA</span></div>\n              </div>\n              <div class=\"chart\" id=\"mhProd\"></div>\n            </div>\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_mhWrk:0\">إجمالي العاملين</h4><span class=\"en\" data-i18n=\"c_mhWrk:1\">TOPLAM ÇALIŞAN K.Ş.</span></div>\n              </div>\n              <div class=\"chart\" id=\"mhWrk\"></div>\n            </div>\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_mhSam:0\">متوسط زمن الموديل</h4><span class=\"en\" data-i18n=\"c_mhSam:1\">ORT. MODEL ZAMANI</span></div>\n              </div>\n              <div class=\"chart\" id=\"mhSam\"></div>\n            </div>\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_mhOt:0\">نسبة الأوفر تايم</h4><span class=\"en\" data-i18n=\"c_mhOt:1\">FAZLA MESAİ ORANI</span></div>\n              </div>\n              <div class=\"chart\" id=\"mhOt\"></div>\n            </div>\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_mhAbs:0\">نسبة الغياب</h4><span class=\"en\" data-i18n=\"c_mhAbs:1\">DEVAMSIZLIK ORANI</span></div>\n              </div>\n              <div class=\"chart\" id=\"mhAbs\"></div>\n            </div>\n          </div>\n        </section>\n\n        <!-- ========== Lines ========== -->\n        <section class=\"page\" id=\"page-lines\">\n          <div class=\"kpi-grid strip\" id=\"lnKpis\"></div>\n          <div class=\"grid-main2 sp-16\">\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_lnAchv:0\">نسبة تحقيق الخطوط</h4><span class=\"en\" data-i18n=\"c_lnAchv:1\">LINE&nbsp;ACHIEVEMENT</span></div>\n              </div>\n              <div class=\"chart\" id=\"lnAchv\"></div>\n            </div>\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_lnActual:0\">الإنتاج الفعلي لكل خط</h4><span class=\"en\" data-i18n=\"c_lnActual:1\">ACTUAL&nbsp;BY&nbsp;LINE</span></div>\n              </div>\n              <div class=\"chart\" id=\"lnActual\"></div>\n            </div>\n          </div>\n          <div class=\"card\">\n            <div class=\"card-head\">\n              <div><h4 data-i18n=\"c_lnTable:0\">تفاصيل الخطوط</h4><span class=\"en\" data-i18n=\"c_lnTable:1\">LINE&nbsp;DETAILS</span></div>\n              <span class=\"chip num\" id=\"lnTblChip\"></span>\n            </div>\n            <div class=\"tbl-wrap\">\n              <table class=\"tbl\" id=\"lnTable\"></table>\n            </div>\n          </div>\n        </section>\n\n        <!-- ========== Supervisors ========== -->\n        <section class=\"page\" id=\"page-sups\">\n          <div class=\"su-tabs\" id=\"suTabs\" role=\"group\" aria-label=\"تصنيف المشرفين\">\n            <a class=\"su-tab\" data-suview=\"sup\" href=\"?page=sups&amp;su=sup\" data-i18n=\"su_sup\">مشرفي الأقسام</a>\n            <a class=\"su-tab\" data-suview=\"leader\" href=\"?page=sups&amp;su=leader\" data-i18n=\"su_leader\">رؤساء الخطوط</a>\n            <a class=\"su-tab\" data-suview=\"mgr\" href=\"?page=sups&amp;su=mgr\" data-i18n=\"su_mgr\">مديري الصالة</a>\n          </div>\n          <div class=\"su-prompt\" id=\"suPrompt\">\n            <svg viewBox=\"0 0 24 24\" width=\"36\" height=\"36\" fill=\"none\" stroke=\"#D9A86B\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3.5 20.5 18.5 5.5\"/><path d=\"m18.5 5.5-2.3 6.3\"/><circle cx=\"14.6\" cy=\"8.6\" r=\"1.1\" fill=\"#D9A86B\" stroke=\"none\"/><path d=\"M6 21.5q5.5.5 7.5-2.8\"/><path d=\"M6 21.5 3.5 20.5\"/></svg>\n            <h4 data-i18n=\"su_pick_t\">اختار التصنيف اللي عايز تشوفه</h4>\n            <p data-i18n=\"su_pick_p\">اضغط على واحد من التلات أزرار فوق</p>\n          </div>\n          <div class=\"su-view\" id=\"suView\">\n          <div class=\"kpi-grid strip\" id=\"svKpis\"></div>\n          <div class=\"grid-2 sp-16\">\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_svTop:0\">الأعلى إنجازًا</h4><span class=\"en\" data-i18n=\"c_svTop:1\">TOP&nbsp;PERFORMERS</span></div>\n              </div>\n              <div class=\"chart\" id=\"svTop\"></div>\n            </div>\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_svBottom:0\">يحتاجون متابعة</h4><span class=\"en\" data-i18n=\"c_svBottom:1\">NEEDS&nbsp;ATTENTION</span></div>\n              </div>\n              <div class=\"chart\" id=\"svBottom\"></div>\n            </div>\n          </div>\n          <div class=\"card\">\n            <div class=\"card-head\">\n              <div><h4 data-i18n=\"c_svTable:0\">أداء المشرفين</h4><span class=\"en\" data-i18n=\"c_svTable:1\">SUPERVISOR&nbsp;DETAILS</span></div>\n              <span class=\"chip num\" id=\"svTblChip\"></span>\n            </div>\n            <div class=\"tbl-wrap\">\n              <table class=\"tbl\" id=\"svTable\"></table>\n            </div>\n          </div>\n          </div><!-- /suView -->\n        </section>\n\n        <!-- ========== Sections ========== -->\n        <section class=\"page\" id=\"page-sections\">\n          <div class=\"kpi-grid strip\" id=\"scKpis\"></div>\n          <div class=\"grid-main2 sp-16\">\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_scAchv:0\">نسبة تحقيق الأقسام</h4><span class=\"en\" data-i18n=\"c_scAchv:1\">SECTION&nbsp;ACHIEVEMENT</span></div>\n              </div>\n              <div class=\"chart\" id=\"scAchv\"></div>\n            </div>\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_scActual:0\">الإنتاج الفعلي لكل قسم</h4><span class=\"en\" data-i18n=\"c_scActual:1\">ACTUAL&nbsp;BY&nbsp;SECTION</span></div>\n              </div>\n              <div class=\"chart\" id=\"scActual\"></div>\n            </div>\n          </div>\n          <div class=\"card sp-16\">\n            <div class=\"card-head\">\n              <div><h4 data-i18n=\"c_scTrend:0\">الاتجاه اليومي للأقسام</h4><span class=\"en\" data-i18n=\"c_scTrend:1\">SECTION&nbsp;DAILY&nbsp;TREND</span></div>\n              <span class=\"chip num\" id=\"scTrendChip\"></span>\n            </div>\n            <div class=\"chart\" id=\"scTrend\"></div>\n          </div>\n          <div class=\"card\">\n            <div class=\"card-head\">\n              <div><h4 data-i18n=\"c_scTable:0\">تفاصيل الأقسام</h4><span class=\"en\" data-i18n=\"c_scTable:1\">SECTION&nbsp;DETAILS</span></div>\n              <span class=\"chip num\" id=\"scTblChip\"></span>\n            </div>\n            <div class=\"tbl-wrap\">\n              <table class=\"tbl\" id=\"scTable\"></table>\n            </div>\n          </div>\n        </section>\n\n        <!-- ========== Pocket Machines ========== -->\n        <section class=\"page\" id=\"page-pm\">\n          <div class=\"kpi-grid strip\" id=\"pmKpis\"></div>\n          <div class=\"grid-main2 sp-16\">\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_pmTrend:0\">الاتجاه اليومي للماكينات</h4><span class=\"en\" data-i18n=\"c_pmTrend:1\">PM&nbsp;DAILY&nbsp;TREND</span></div>\n              </div>\n              <div class=\"chart\" id=\"pmTrend\"></div>\n            </div>\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_pmMach:0\">إنجاز الماكينات</h4><span class=\"en\" data-i18n=\"c_pmMach:1\">PM&nbsp;MACHINE&nbsp;ACHIEVEMENT</span></div>\n              </div>\n              <div class=\"chart\" id=\"pmMach\"></div>\n            </div>\n          </div>\n          <div class=\"grid-2\">\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_pmLine:0\">إنتاج الماكينات حسب الخط</h4><span class=\"en\" data-i18n=\"c_pmLine:1\">PM&nbsp;BY&nbsp;LINE</span></div>\n              </div>\n              <div class=\"chart\" id=\"pmLine\"></div>\n            </div>\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_pmTVsA:0\">الهدف مقابل الفعلي حسب الخط</h4><span class=\"en\" data-i18n=\"c_pmTVsA:1\">TARGET&nbsp;VS&nbsp;ACTUAL</span></div>\n              </div>\n              <div class=\"chart\" id=\"pmTVsA\"></div>\n            </div>\n          </div>\n          <div class=\"card\">\n            <div class=\"card-head\">\n              <div><h4 data-i18n=\"c_pmTable:0\">تفاصيل ماكينات الجيوب</h4><span class=\"en\" data-i18n=\"c_pmTable:1\">POCKET&nbsp;MACHINE&nbsp;DETAILS</span></div>\n              <span class=\"chip num\" id=\"pmTblChip\"></span>\n            </div>\n            <div class=\"tbl-wrap\">\n              <table class=\"tbl\" id=\"pmTable\"></table>\n            </div>\n          </div>\n        </section>\n\n        <!-- ========== Overtime ========== -->\n        <section class=\"page\" id=\"page-ot\">\n          <div class=\"kpi-grid strip\" id=\"otKpis\"></div>\n          <div class=\"grid-main2 sp-16\">\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_otDaily:0\">نسبة الأوفر تايم اليومية</h4><span class=\"en\" data-i18n=\"c_otDaily:1\">DAILY&nbsp;OVERTIME&nbsp;%</span></div>\n              </div>\n              <div class=\"chart\" id=\"otDaily\"></div>\n            </div>\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_otGauge:0\">مؤشر الأوفر تايم</h4><span class=\"en\" data-i18n=\"c_otGauge:1\">OVERTIME&nbsp;GAUGE</span></div>\n              </div>\n              <div class=\"chart\" id=\"otGauge\"></div>\n              <div class=\"gauge-note\">\n                <span class=\"dot\" style=\"background:rgba(47,213,131,.7)\"></span><span data-i18n=\"gn_1\">حتى 10%</span>\n                <span class=\"dot\" style=\"background:rgba(245,185,60,.7);margin-inline-start:10px\"></span><span data-i18n=\"gn_2\">10–20%</span>\n                <span class=\"dot\" style=\"background:rgba(248,113,113,.7);margin-inline-start:10px\"></span><span data-i18n=\"gn_3\">فوق 20%</span>\n              </div>\n            </div>\n          </div>\n          <div class=\"grid-2\">\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_otSec:0\">أوفر تايم الأقسام</h4><span class=\"en\" data-i18n=\"c_otSec:1\">OT&nbsp;BY&nbsp;SECTION</span></div>\n              </div>\n              <div class=\"chart\" id=\"otSec\"></div>\n            </div>\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_otSrc:0\">أوفر تايم الخطوط</h4><span class=\"en\" data-i18n=\"c_otSrc:1\">OT&nbsp;BY&nbsp;LINE</span></div>\n              </div>\n              <div class=\"chart\" id=\"otSrc\"></div>\n            </div>\n          </div>\n          <div class=\"card sp-16\">\n            <div class=\"card-head\">\n              <div><h4 data-i18n=\"c_otSup:0\">أوفر تايم المشرفين</h4><span class=\"en\" data-i18n=\"c_otSup:1\">OT&nbsp;BY&nbsp;SUPERVISOR</span></div>\n            </div>\n            <div class=\"chart\" id=\"otSup\"></div>\n          </div>\n          <div class=\"card\">\n            <div class=\"card-head\">\n              <div><h4 data-i18n=\"c_otTable:0\">تفاصيل الأوفر تايم اليومية</h4><span class=\"en\" data-i18n=\"c_otTable:1\">OT&nbsp;DAILY&nbsp;DETAILS</span></div>\n              <span class=\"chip num\" id=\"otTblChip\"></span>\n            </div>\n            <div class=\"tbl-wrap\">\n              <table class=\"tbl\" id=\"otTable\"></table>\n            </div>\n          </div>\n        </section>\n\n        <!-- ========== Attendance ========== -->\n        <section class=\"page\" id=\"page-att\">\n          <div class=\"att-tabs\" id=\"attTabs\">\n            <a class=\"att-tab on\" data-attview=\"workers\" href=\"?page=att&amp;att=workers\" data-i18n=\"at_tab_workers\">حضور وغياب العمال</a>\n            <a class=\"att-tab\" data-attview=\"sups\" href=\"?page=att&amp;att=sups\" data-i18n=\"at_tab_sups\">حضور وغياب المشرفين</a>\n          </div>\n\n          <!-- ===== workers view ===== -->\n          <div class=\"att-view on\" id=\"attWorkers\">\n          <div class=\"kpi-grid strip\" id=\"atKpis\"></div>\n          <div class=\"grid-main2 sp-16\">\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_atHeat:0\">خريطة الانضباط الأسبوعية</h4><span class=\"en\" data-i18n=\"c_atHeat:1\">WEEKLY&nbsp;DISCIPLINE&nbsp;HEATMAP</span></div>\n              </div>\n              <div class=\"chart\" id=\"atHeat\"></div>\n            </div>\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_atDow:0\">متوسط الحضور حسب اليوم</h4><span class=\"en\" data-i18n=\"c_atDow:1\">ATTENDANCE&nbsp;BY&nbsp;WEEKDAY</span></div>\n              </div>\n              <div class=\"chart\" id=\"atDow\"></div>\n            </div>\n          </div>\n          <div class=\"grid-2\">\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_atDaily:0\">الحضور اليومي</h4><span class=\"en\" data-i18n=\"c_atDaily:1\">DAILY&nbsp;ATTENDANCE</span></div>\n              </div>\n              <div class=\"chart\" id=\"atDaily\"></div>\n            </div>\n            <div class=\"card\">\n              <div class=\"card-head\">\n                <div><h4 data-i18n=\"c_atAbsent:0\">إجمالي الغياب حسب اليوم</h4><span class=\"en\" data-i18n=\"c_atAbsent:1\">ABSENCES&nbsp;BY&nbsp;WEEKDAY</span></div>\n              </div>\n              <div class=\"chart\" id=\"atAbsent\"></div>\n            </div>\n          </div>\n          <div class=\"card\">\n            <div class=\"card-head\">\n              <div><h4 data-i18n=\"c_atTable:0\">تفاصيل الحضور اليومية</h4><span class=\"en\" data-i18n=\"c_atTable:1\">ATTENDANCE&nbsp;DAILY&nbsp;DETAILS</span></div>\n              <span class=\"chip num\" id=\"atTblChip\"></span>\n            </div>\n            <div class=\"tbl-wrap\">\n              <table class=\"tbl\" id=\"atTable\"></table>\n            </div>\n          </div>\n          </div>\n\n          <!-- ===== supervisors view ===== -->\n          <div class=\"att-view\" id=\"attSups\">\n          <div class=\"kpi-grid strip\" id=\"asKpis\"></div>\n          <div class=\"card\">\n            <div class=\"card-head\">\n              <div><h4 data-i18n=\"c_asDaily:0\">المشرفون الحاضرون يوميًا</h4><span class=\"en\" data-i18n=\"c_asDaily:1\">SUPERVISORS&nbsp;PRESENT&nbsp;DAILY</span></div>\n            </div>\n            <div class=\"chart\" id=\"asDaily\"></div>\n          </div>\n          <div class=\"card\">\n            <div class=\"card-head\">\n              <div><h4 data-i18n=\"c_asTable:0\">انضباط المشرفين</h4><span class=\"en\" data-i18n=\"c_asTable:1\">SUPERVISOR&nbsp;DISCIPLINE</span></div>\n              <span class=\"chip num\" id=\"asTblChip\"></span>\n            </div>\n            <div class=\"tbl-wrap\">\n              <table class=\"tbl\" id=\"asTable\"></table>\n            </div>\n          </div>\n          </div>\n        </section>\n\n        <!-- ========== Data — cloud sync (R23 #9) ========== -->\n        <section class=\"page\" id=\"page-data\">\n          <div class=\"card\">\n            <div class=\"card-head\">\n              <div><h4 data-i18n=\"dt_sync\">مزامنة البيانات</h4><span class=\"en\">DATA&nbsp;SYNC</span></div>\n              <span class=\"chip num\" id=\"dtSyncChip\"></span>\n            </div>\n            <div class=\"dt-hero\">\n              <button class=\"dt-btn\" id=\"dtFolder\" type=\"button\">\n                <span class=\"ic\"><svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3.5 7.2q0-1.7 1.7-1.7h4l2 2.4h7.6q1.7 0 1.7 1.7v8.2q0 1.7-1.7 1.7H5.2q-1.7 0-1.7-1.7z\"/></svg></span>\n                <span><b data-i18n=\"dt_folder_t\">رفع مجلد الشهر</b><small data-i18n=\"dt_folder_d\">اختار مجلد فيه ملف إكسل الشهر</small></span>\n              </button>\n              <button class=\"dt-btn\" id=\"dtExcel\" type=\"button\">\n                <span class=\"ic\"><svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M14 3.5H6.8q-1.3 0-1.3 1.3v14.4q0 1.3 1.3 1.3h10.4q1.3 0 1.3-1.3V8z\"/><path d=\"M14 3.5V8h4.5\"/><path d=\"M8.3 12.5h2.4M8.3 15.5h2.4M8.3 18h4.4\"/></svg></span>\n                <span><b data-i18n=\"dt_excel_t\">رفع ملف Excel</b><small data-i18n=\"dt_excel_d\">اختار ملف xlsx واحد</small></span>\n              </button>\n            </div>\n          </div>\n          <div class=\"card\">\n            <div class=\"card-head\">\n              <div><h4 data-i18n=\"dt_months_head\">الأشهر المتزامنة على السيرفر</h4><span class=\"en\">SYNCED&nbsp;MONTHS</span></div>\n            </div>\n            <div class=\"tbl-wrap\">\n              <table class=\"tbl dt-months-tbl\" id=\"dtMonths\"></table>\n            </div>\n          </div>\n        </section>\n\n      </div>\n    </main>\n  </div>\n</div>\n\n<!-- ================= Settings panel (R27 — categorized boxes) =================\n     Level 1: a grid of category boxes (#setHome). Clicking a box opens\n     its settings view (level 2) with a back button in the header.\n     Boxes are role-filtered by openSettings(): targets=admin+,\n     groups=everyone, audit+storage=dev only. All inner IDs are the\n     SAME as the old accordion sections — existing bindings untouched. -->\n<div class=\"set-pop\" id=\"setPop\">\n  <div class=\"set-panel\">\n    <div class=\"dp-head\">\n      <button class=\"icon-btn set-back\" id=\"setBack\" type=\"button\" hidden data-i18n-title=\"st_back\" title=\"رجوع للإعدادات\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M15 5l-7 7 7 7\"/></svg>\n      </button>\n      <div>\n        <h3 id=\"setTitle\" data-i18n=\"set_title\">الإعدادات</h3>\n        <span class=\"sub\" id=\"setSub\" data-i18n=\"set_sub\">SETTINGS</span>\n      </div>\n      <button class=\"icon-btn\" id=\"setClose\" title=\"إغلاق\" data-i18n-title=\"dp_close\" type=\"button\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\"><path d=\"M6 6l12 12M18 6 6 18\"/></svg>\n      </button>\n    </div>\n\n    <!-- level 1: category boxes -->\n    <div class=\"set-home\" id=\"setHome\">\n      <button class=\"set-box\" data-view=\"targets\" type=\"button\">\n        <span class=\"sb-ic\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><circle cx=\"12\" cy=\"12\" r=\"5\"/><circle cx=\"12\" cy=\"12\" r=\"1.2\" fill=\"currentColor\"/></svg></span>\n        <span class=\"sb-tx\"><b data-i18n=\"set_targets\">الأهداف والحدود</b><small data-i18n=\"sb_d_targets\">خطوط الهدف وألوان الحالة على كل الرسومات والجداول</small></span>\n        <span class=\"sb-go\">‹</span>\n      </button>\n      <button class=\"set-box\" data-view=\"groups\" type=\"button\">\n        <span class=\"sb-ic\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"9\" cy=\"8\" r=\"3.4\"/><path d=\"M2.5 19c.6-3.2 3.2-5 6.5-5s5.9 1.8 6.5 5\"/><circle cx=\"17\" cy=\"9\" r=\"2.6\"/><path d=\"M16.2 14.4c2.6.2 4.6 1.9 5.2 4.6\"/></svg></span>\n        <span class=\"sb-tx\"><b data-i18n=\"set_groups\">تصنيف المشرفين</b><small data-i18n=\"sb_d_groups\">توزيع المشرفين ورؤساء الخطوط ومديري الصالة على مجموعاتهم</small></span>\n        <span class=\"sb-go\">‹</span>\n      </button>\n      <button class=\"set-box\" data-view=\"audit\" type=\"button\">\n        <span class=\"sb-ic\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 4.5h14v15H5z\"/><path d=\"M9 9h6M9 12.5h6M9 16h3.5\"/></svg></span>\n        <span class=\"sb-tx\"><b data-i18n=\"set_audit\">سجل العمليات</b><small data-i18n=\"sb_d_audit\">كل عملية ورفع وتعديل حصل على الموقع ومَن عمله</small></span>\n        <span class=\"sb-go\">‹</span>\n      </button>\n      <button class=\"set-box\" data-view=\"mhome\" type=\"button\">\n        <span class=\"sb-ic\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 11l8-7 8 7\"/><path d=\"M6 9.5V20h12V9.5\"/><path d=\"M10 20v-6h4v6\"/></svg></span>\n        <span class=\"sb-tx\"><b data-i18n=\"set_mhome\">رئيسية المدير</b><small data-i18n=\"sb_d_mhome\">تحديد مين يشوف شكل الرئيسية الجديد</small></span>\n        <span class=\"sb-go\">‹</span>\n      </button>\n      <button class=\"set-box\" data-view=\"storage\" type=\"button\">\n        <span class=\"sb-ic\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><ellipse cx=\"12\" cy=\"5.5\" rx=\"8\" ry=\"3\"/><path d=\"M4 5.5v6c0 1.7 3.6 3 8 3s8-1.3 8-3v-6\"/><path d=\"M4 11.5v6c0 1.7 3.6 3 8 3s8-1.3 8-3v-6\"/></svg></span>\n        <span class=\"sb-tx\"><b data-i18n=\"set_storage\">مساحة قاعدة البيانات</b><small data-i18n=\"sb_d_storage\">المساحة المستخدمة من قاعدة البيانات وحجم خطتك</small></span>\n        <span class=\"sb-go\">‹</span>\n      </button>\n    </div>\n    <p class=\"set-home-hint\" data-i18n=\"sb_hint\">اضغط على القسم اللي عايز تعدّله</p>\n\n    <!-- level 2: views (hidden until their box is clicked) -->\n    <div class=\"set-view\" id=\"setView-targets\" hidden>\n      <div class=\"tg-grid\" id=\"tgGrid\">\n        <div class=\"tg-row\">\n          <span class=\"tg-name\" data-i18n=\"tg_achv\">نسبة التحقيق</span>\n          <label><i data-i18n=\"tg_goal\">الهدف</i><input type=\"number\" id=\"tgAchvGood\" min=\"1\" max=\"100\" step=\"0.5\"><u>%</u></label>\n          <label><i data-i18n=\"tg_warn\">تحذير</i><input type=\"number\" id=\"tgAchvWarn\" min=\"1\" max=\"100\" step=\"0.5\"><u>%</u></label>\n        </div>\n        <div class=\"tg-row\">\n          <span class=\"tg-name\" data-i18n=\"tg_eff\">الكفاءة</span>\n          <label><i data-i18n=\"tg_goal\">الهدف</i><input type=\"number\" id=\"tgEffGood\" min=\"1\" max=\"100\" step=\"0.5\"><u>%</u></label>\n          <label><i data-i18n=\"tg_warn\">تحذير</i><input type=\"number\" id=\"tgEffWarn\" min=\"1\" max=\"100\" step=\"0.5\"><u>%</u></label>\n        </div>\n        <div class=\"tg-row\">\n          <span class=\"tg-name\" data-i18n=\"tg_ot\">الأوفر تايم</span>\n          <label><i data-i18n=\"tg_safe\">حد آمن</i><input type=\"number\" id=\"tgOtGood\" min=\"0.5\" max=\"100\" step=\"0.5\"><u>%</u></label>\n          <label><i data-i18n=\"tg_danger\">خطر</i><input type=\"number\" id=\"tgOtWarn\" min=\"0.5\" max=\"100\" step=\"0.5\"><u>%</u></label>\n        </div>\n        <div class=\"tg-row\">\n          <span class=\"tg-name\" data-i18n=\"tg_att\">الحضور</span>\n          <label><i data-i18n=\"tg_goal\">الهدف</i><input type=\"number\" id=\"tgAttGood\" min=\"1\" max=\"100\" step=\"0.5\"><u>%</u></label>\n          <label><i data-i18n=\"tg_warn\">تحذير</i><input type=\"number\" id=\"tgAttWarn\" min=\"1\" max=\"100\" step=\"0.5\"><u>%</u></label>\n        </div>\n      </div>\n      <div class=\"tg-apply\" id=\"tgApply\">\n        <p class=\"set-hint\" style=\"flex:1 1 100%;margin:2 0 4\" data-i18n=\"tg_apply_t\">دلوقتي الهدف الجديد ده بيشتغل من امتى؟</p>\n        <label><input type=\"radio\" name=\"tgApplyMode\" value=\"now\" checked><span><b data-i18n=\"tg_from_now\">من الآن فما بعد</b><small data-i18n=\"tg_from_now_d\">التواريخ القديمة هتفضل على الأهداف القديمة</small></span></label>\n        <label><input type=\"radio\" name=\"tgApplyMode\" value=\"retro\"><span><b data-i18n=\"tg_retro\">يشمل التواريخ القديمة كمان</b><small data-i18n=\"tg_retro_d\">الهدف الجديد بيتطبق على كل الفترات</small></span></label>\n      </div>\n      <p class=\"admin-only-note\" id=\"tgAdminNote\" data-i18n=\"tg_admin_note\">الأهداف للأدمن بس</p>\n      <div class=\"tg-btns\">\n        <button class=\"tg-save\" id=\"tgSave\" type=\"button\" data-i18n=\"tg_save\">حفظ الأهداف</button>\n        <button class=\"tg-reset\" id=\"tgReset\" type=\"button\" data-i18n=\"tg_reset\">القيم الافتراضية</button>\n      </div>\n      <p class=\"tg-note\" data-i18n=\"tg_note_cloud\">الأهداف تُحفظ على السيرفر</p>\n    </div>\n\n    <div class=\"set-view\" id=\"setView-groups\" hidden>\n      <span class=\"cls-label\" data-i18n=\"su_cat\">تصنيف المشرفين</span>\n      <div class=\"seg\" id=\"clsFilter\">\n        <button class=\"seg-btn on\" data-g=\"sup\" data-i18n=\"su_sup\" type=\"button\">مشرفي الأقسام</button>\n        <button class=\"seg-btn\" data-g=\"leader\" data-i18n=\"su_leader\" type=\"button\">رؤساء الخطوط</button>\n        <button class=\"seg-btn\" data-g=\"mgr\" data-i18n=\"su_mgr\" type=\"button\">مديري الصالة</button>\n      </div>\n      <p class=\"set-hint\" data-i18n=\"cls_hint\">كل اسم بيتحط في مجموعته</p>\n      <div class=\"cls-people\" id=\"clsPeople\"></div>\n      <p class=\"cls-count\" id=\"clsCount\"></p>\n      <div class=\"tg-btns\">\n        <button class=\"tg-save\" id=\"clsSave\" type=\"button\" data-i18n=\"cls_save\">حفظ التصنيف</button>\n      </div>\n    </div>\n\n    <div class=\"set-view\" id=\"setView-mhome\" hidden>\n      <p class=\"set-hint\" data-i18n=\"mh_hint\">علّم الأشخاص اللي هيشوفوا الشكل الجديد</p>\n      <div class=\"mh-users\" id=\"mhUsers\"></div>\n      <p class=\"cls-count\" id=\"mhCount\"></p>\n      <div class=\"tg-btns\">\n        <button class=\"tg-save\" id=\"mhSave\" type=\"button\" data-i18n=\"mh_save\">حفظ</button>\n      </div>\n    </div>\n\n    <div class=\"set-view\" id=\"setView-audit\" hidden>\n      <p class=\"set-hint\" data-i18n=\"au_hint\">السجل بيتسجل تلقائيًا</p>\n      <div class=\"au-step\"><b data-i18n=\"au_step1\">حدد التاريخ الأول</b><small data-i18n=\"au_step1_d\">من امتى وإلى امتى عايز سجل العمليات؟</small></div>\n      <div class=\"au-bar\">\n        <input type=\"date\" id=\"auFrom\" title=\"من\" data-i18n-title=\"f_from\">\n        <input type=\"date\" id=\"auTo\" title=\"إلى\" data-i18n-title=\"f_to\">\n        <button class=\"au-x-btn ghost\" id=\"auAll\" type=\"button\" data-i18n=\"au_all_time\">من ساعة إنشاء الموقع</button>\n      </div>\n      <div class=\"au-step\"><b data-i18n=\"au_step2\">بعد كده اختار</b><small data-i18n=\"au_step2_d\">تشوف العمليات على الموقع ولا تنزّلها ملف إكسل xlsx</small></div>\n      <div class=\"au-actions\">\n        <button class=\"au-x-btn au-view\" id=\"auShow\" type=\"button\" disabled>\n          <svg viewBox=\"0 0 24 24\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M2.5 12s3.5-6.5 9.5-6.5 9.5 6.5 9.5 6.5-3.5 6.5-9.5 6.5S2.5 12 2.5 12z\"/><circle cx=\"12\" cy=\"12\" r=\"2.8\"/></svg>\n          <span data-i18n=\"au_show\">عرض على الموقع</span>\n        </button>\n        <button class=\"au-x-btn\" id=\"auExport\" type=\"button\" disabled>\n          <svg viewBox=\"0 0 24 24\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 3.6v11.8m0 0-4.1-4.1M12 15.4l4.1-4.1M4.5 19.5h15\"/></svg>\n          <span data-i18n=\"au_export\">تنزيل إكسل xlsx</span>\n        </button>\n      </div>\n      <p class=\"au-pick-hint\" id=\"auPickHint\" data-i18n=\"au_pick\">لسه محددتش فترة — اختار تاريخ من فوق أو دوس «من ساعة إنشاء الموقع»، وبعدين اختار عرض أو تنزيل</p>\n      <div id=\"auTables\" hidden>\n        <h4 class=\"au-h\" style=\"color:#E9C68A;font-size:12.5px;margin:12px 0 6px\" data-i18n=\"au_entities\">الأنشطة والتعديلات</h4>\n        <div class=\"au-wrap\"><table class=\"au-tbl\" id=\"auEntities\"></table></div>\n        <h4 style=\"color:#E9C68A;font-size:12.5px;margin:14px 0 6px\" data-i18n=\"au_events\">كل العمليات</h4>\n        <div class=\"au-wrap\"><table class=\"au-tbl\" id=\"auEvents\"></table></div>\n      </div>\n    </div>\n\n    <div class=\"set-view\" id=\"setView-storage\" hidden>\n      <p class=\"set-hint\" data-i18n=\"stg_hint\">المساحة بتتقاس من قاعدة Neon</p>\n      <div class=\"stg-bar\"><i id=\"stgFill\" style=\"width:0%\"></i></div>\n      <div class=\"stg-meta\">\n        <span><b id=\"stgUsed\">—</b> <span data-i18n=\"stg_used\">المستخدم</span></span>\n        <span><span data-i18n=\"stg_of\">من</span> <b id=\"stgQuota\">—</b></span>\n        <span><b class=\"num\" id=\"stgPct\">—</b></span>\n      </div>\n      <div class=\"stg-quota\">\n        <span style=\"color:#A9B7C7;font-size:11.5px;font-weight:700\" data-i18n=\"stg_quota\">حجم خطتك</span>\n        <input type=\"number\" id=\"stgQuotaIn\" min=\"0.1\" step=\"0.5\" value=\"3\">\n        <span style=\"color:#7E92A8;font-size:11px\" data-i18n=\"stg_gb\">GB</span>\n        <button id=\"stgSave\" type=\"button\" data-i18n=\"stg_save\">حفظ الحجم</button>\n      </div>\n      <div style=\"display:flex;gap:16px;flex-wrap:wrap;margin-top:12px;color:#A9B7C7;font-size:11.5px\">\n        <span><b class=\"num\" id=\"stgRows\">—</b> <span data-i18n=\"stg_rows\">صفوف</span></span>\n        <span><b class=\"num\" id=\"stgMonths\">—</b> <span data-i18n=\"stg_months\">أشهر</span></span>\n      </div>\n      <h4 style=\"color:#E9C68A;font-size:12.5px;margin:14px 0 6px\" data-i18n=\"stg_top\">أكبر الجداول</h4>\n      <div class=\"au-wrap\"><table class=\"au-tbl\" id=\"stgTables\"></table></div>\n    </div>\n  </div>\n</div>\n\n<!-- ================= Users & roles modal (round 10) ================= -->\n<div class=\"data-pop\" id=\"usPop\">\n  <div class=\"dp-panel us-panel\">\n    <div class=\"dp-head\">\n      <div>\n        <h3 data-i18n=\"us_title\">المستخدمين والصلاحيات</h3>\n        <span class=\"sub\" data-i18n=\"us_sub\">USERS&nbsp;&amp;&nbsp;ROLES</span>\n      </div>\n      <button class=\"icon-btn\" id=\"usClose\" title=\"إغلاق\" data-i18n-title=\"dp_close\" type=\"button\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\"><path d=\"M6 6l12 12M18 6 6 18\"/></svg>\n      </button>\n    </div>\n    <div class=\"us-list\" id=\"usList\"></div>\n    <div class=\"us-add\">\n      <h4 data-i18n=\"us_add_title\">مستخدم جديد</h4>\n      <div class=\"us-add-row\">\n        <input type=\"text\" id=\"usName\" autocomplete=\"off\" spellcheck=\"false\" data-i18n-ph=\"us_name_ph\" data-i18n-aria=\"us_name_ph\" placeholder=\"اسم المستخدم\">\n        <input type=\"text\" id=\"usPass\" autocomplete=\"off\" data-i18n-ph=\"us_pass_ph\" data-i18n-aria=\"us_pass_ph\" placeholder=\"كلمة المرور\">\n      </div>\n      <label class=\"us-chk\">\n        <input type=\"checkbox\" id=\"usAdmin\"><i></i><span data-i18n=\"us_admin_lbl\">صلاحيات أدمن</span>\n      </label>\n      <button class=\"us-add-btn\" id=\"usAddBtn\" type=\"button\" data-i18n=\"us_add\">إضافة المستخدم</button>\n      <p class=\"us-note\" data-i18n=\"us_admin_hint\">الأدمن يقدر يضيف ويعدّل ويحذف المستخدمين — الحساب العادي بيشوف اللوحة بس</p>\n    </div>\n  </div>\n</div>\n\n<!-- ================= Drill-through modal ================= -->\n<div class=\"drill\" id=\"drill\">\n  <div class=\"drill-panel\">\n    <div class=\"drill-head\">\n      <div>\n        <h3 id=\"drillTitle\">—</h3>\n        <span class=\"sub\" id=\"drillSub\">DETAILS</span>\n      </div>\n      <button class=\"icon-btn\" id=\"drillClose\" title=\"رجوع\" data-i18n-title=\"d_close\" type=\"button\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\"><path d=\"M6 6l12 12M18 6 6 18\"/></svg>\n      </button>\n    </div>\n    <div class=\"drill-kpis\" id=\"drillKpis\"></div>\n    <div class=\"card\" style=\"margin-bottom:14px\">\n      <div class=\"card-head\">\n        <div><h4 id=\"drillChartTitle\" data-i18n=\"c_drillTrend:0\">الاتجاه اليومي</h4><span class=\"en\" data-i18n=\"c_drillTrend:1\">DAILY&nbsp;TREND</span></div>\n      </div>\n      <div class=\"chart\" id=\"drillChart\"></div>\n    </div>\n    <div class=\"card\">\n      <div class=\"card-head\">\n        <div><h4 data-i18n=\"c_drillTable:0\">السجلات التفصيلية</h4><span class=\"en\" data-i18n=\"c_drillTable:1\">DETAIL&nbsp;RECORDS</span></div>\n        <span class=\"chip num\" id=\"drillTblChip\"></span>\n      </div>\n      <div class=\"tbl-wrap\">\n        <table class=\"tbl\" id=\"drillTable\"></table>\n      </div>\n    </div>\n  </div>\n</div>\n\n\n<!-- ================= R37: الاتزان — manpower balance app =================\n     Hierarchy: الإدارة levels → الوظيفة → الموظف (name + code), with\n     actual/required/variance at every node + the transfer archive. -->\n<div class=\"mp-wrap\" id=\"mpWrap\" lang=\"ar\" hidden>\n  <header class=\"mp-top\">\n    <div class=\"mp-brand\">\n      <span class=\"mp-ico\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3v18\"/><path d=\"M8 21h8\"/><path d=\"M4.5 7h15\"/><path d=\"M6.5 7 4 12.2a3 3 0 0 0 5.6 0L7 12.2\"/><path d=\"M17.5 7 15 12.2a3 3 0 0 0 5.6 0L18 12.2\"/><path d=\"M12 5.2 6.5 7M12 5.2 17.5 7\"/></svg></span>\n      <div class=\"mp-t\">\n        <h2 data-i18n=\"mg_mp\">الاتزان</h2>\n        <small data-i18n=\"mg_mp_sub\">هيكل القوى العاملة والأعداد</small>\n      </div>\n    </div>\n    <div class=\"mp-top-ctrls\">\n      <div class=\"mp-tabs\">\n        <button class=\"mp-tab on\" id=\"mpTabTree\" type=\"button\" data-i18n=\"mp_tree_tab\">الهيكل</button>\n        <button class=\"mp-tab\" id=\"mpTabArch\" type=\"button\" data-i18n=\"mp_archive\">أرشيف النقل</button>\n      </div>\n      \n      <div class=\"lang-sw mp-lang\" id=\"mpLang\">\n        <button class=\"sw-btn on\" data-lang=\"ar\" type=\"button\" title=\"العربية\">ع</button>\n        <button class=\"sw-btn\" data-lang=\"en\" type=\"button\" title=\"English\">EN</button>\n        <button class=\"sw-btn\" data-lang=\"tr\" type=\"button\" title=\"Türkçe\">TR</button>\n      </div>\n      <button class=\"mp-back\" id=\"mpBack\" type=\"button\" data-i18n-title=\"home_btn\" title=\"الصفحة الرئيسية\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 11l9-8 9 8\"/><path d=\"M5 9.5V21h14V9.5\"/><path d=\"M9.5 21v-6h5v6\"/></svg><span data-i18n=\"home_btn\">الصفحة الرئيسية</span>\n      </button>\n    </div>\n  </header>\n\n  <div class=\"mp-hero\" id=\"mpHero\"></div>\n\n  <div class=\"mp-body\">\n    <section class=\"mp-view on\" id=\"mpViewTree\" aria-label=\"hierarchy\">\n      <div class=\"mp-tools\">\n        <input class=\"mp-search\" id=\"mpSearch\" type=\"search\" autocomplete=\"off\" spellcheck=\"false\"\n               data-i18n-ph=\"mp_search_ph\" placeholder=\"ابحث: إدارة، وظيفة، اسم أو كود…\" aria-label=\"search\">\n        <button class=\"mp-mini\" id=\"mpExpandAll\" type=\"button\" data-i18n=\"mp_expand_all\">فتح الكل</button>\n        <button class=\"mp-mini\" id=\"mpCollapseAll\" type=\"button\" data-i18n=\"mp_collapse_all\">تقفيل الكل</button>\n        <span class=\"mp-flex\"></span>\n        <button class=\"mp-act\" id=\"mpDeptBtn\" type=\"button\" data-i18n=\"mp_dept_add\">إضافة قسم</button>\n        <button class=\"mp-act\" id=\"mpImportBtn\" type=\"button\" data-i18n=\"mp_upload\">رفع شيت Manpower</button>\n        <button class=\"mp-act\" id=\"mpAddBtn\" type=\"button\" data-i18n=\"mp_add_emp\">إضافة موظف</button>\n      </div>\n      <div class=\"mp-thead\" id=\"mpThead\">\n        <span class=\"th-name\" id=\"thName\" data-i18n=\"mp_item\">القسم / الموظف</span>\n        <span class=\"th-num\" data-i18n=\"mp_actual\">الحالي</span>\n        <span class=\"th-num\" data-i18n=\"mp_required\">المطلوب</span>\n        <span class=\"th-num\" data-i18n=\"mp_variance\">الفرق</span>\n      </div>\n      <div class=\"mp-tree\" id=\"mpTree\" role=\"tree\" aria-label=\"manpower hierarchy\"></div>\n      <div class=\"mp-empty\" id=\"mpEmpty\" hidden><span data-i18n=\"mp_search_none\">مفيش نتائج للبحث</span></div>\n      <div class=\"mp-empty\" id=\"mpLoading\" hidden><span data-i18n=\"mp_loading\">جاري التحميل…</span></div>\n    </section>\n\n    <section class=\"mp-view\" id=\"mpViewArch\" aria-label=\"transfer archive\">\n      <div class=\"mp-tools\">\n        <input class=\"mp-search\" id=\"mpArchSearch\" type=\"search\" autocomplete=\"off\" spellcheck=\"false\"\n               data-i18n-ph=\"mp_arch_search\" placeholder=\"ابحث في الأرشيف…\" aria-label=\"archive search\">\n      </div>\n      <div class=\"mp-arch\" id=\"mpArch\"></div>\n      <div class=\"mp-empty\" id=\"mpArchEmpty\" hidden><span data-i18n=\"mp_no_transfers\">مفيش عمليات نقل لسه</span></div>\n    </section>\n  </div>\n  <input type=\"file\" id=\"mpXlsxPick\" accept=\".xlsx,.xlsm\" hidden>\n</div>\n<div id=\"tip\"></div>\n<div id=\"toast\"></div>\n<div id=\"dropZone\">\n  <div class=\"inner\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3.6v11.8m0 0-4.1-4.1M12 15.4l4.1-4.1M4.5 19.5h15\"/></svg>\n    <p data-i18n=\"dz_main\">أفلت ملفات أو مجلد Excel هنا</p>\n    <small data-i18n=\"dz_sub\">يتم التحليل مباشرة على جهازك — بدون إنترنت</small>\n  </div>\n</div>\n<input type=\"file\" id=\"dirPick\" webkitdirectory multiple hidden>\n<input type=\"file\" id=\"xlsxPick\" accept=\".xlsx,.xlsm\" hidden>\n";
